import { field, textarea, select, checkbox, htmlEscape, attrEscape } from "../tool-core.js";export default {form: `<div class="field-grid">${field({ id: "dsdHost", label: "Host element tag", help: "Must include a hyphen for valid custom element names. e.g. my-widget, user-card", value: "my-widget" })}${select({ id: "dsdMode", label: "Shadow root mode", options: [{label:"Open",value:"open"},{label:"Closed",value:"closed"}], value: "open" })}</div><div class="field-grid">${textarea({ id: "dsdContent", label: "Shadow DOM inner HTML", help: "HTML content inside the shadow root. Use slots for projection.", value: "<h2><slot name=\"heading\">Default heading</slot></h2>\n<p><slot>Default content</slot></p>" })}${textarea({ id: "dsdCSS", label: "Scoped CSS (optional)", help: "CSS scoped to this shadow root.", value: "h2 { color: var(--color-heading, #333); }\np { line-height: 1.6; }" })}</div><div class="field-grid">${checkbox({ id: "dsdFallback", label: "Include fallback content", checked: true })}${field({ id: "dsdFallbackText", label: "Fallback text", help: "Shown when declarative shadow DOM is not supported.", value: "Content requires a modern browser with Declarative Shadow DOM support." })}</div>`,generate(root) {const host = root.querySelector("#dsdHost").value.trim() || "my-widget";const mode = root.querySelector("#dsdMode").value;const content = root.querySelector("#dsdContent").value.trim();const css = root.querySelector("#dsdCSS").value.trim();const includeFallback = root.querySelector("#dsdFallback").checked;const fallbackText = root.querySelector("#dsdFallbackText").value.trim();if (!host.includes("-")) {return { output: `The host element tag "${host}" must include a hyphen (-) for valid custom element names. Examples: my-widget, user-card, nav-bar.` };}const lines = [];lines.push(`<${host}>`);lines.push(` <template shadowrootmode="${mode}">`);if (css) {lines.push(` <style>`);css.split("\n").forEach(l => lines.push(` ${l}`));lines.push(` </style>`);}content.split("\n").forEach(l => lines.push(` ${l}`));lines.push(` </template>`);if (includeFallback) {lines.push(` <div class="dsd-fallback" style="display:none" aria-hidden="true">`);lines.push(` ${htmlEscape(fallbackText)}`);lines.push(` </div>`);}lines.push(`</${host}>`);lines.push("");lines.push("/* === Declarative Shadow DOM === */",`/* Mode: ${mode} — ${mode === "open" ? "shadow root accessible via element.shadowRoot" : "shadow root not accessible from JavaScript"} */`,"/* The browser creates a shadow root from the template without JavaScript. */","/* Supported in: Chrome 90+, Edge 90+, Safari 17+. Firefox support is in development. */","","/* Server-side rendering: include this markup in your SSR output. */","/* The browser streams and renders the shadow DOM before the first paint. */","","/* Fallback styling hint: */","/* .dsd-fallback { display: block !important; } — shown when DSD is unsupported */","/* @supports not (selector(template[shadowrootmode])) { .dsd-fallback { display: block !important; } } */");return { output: lines.join("\n") };}};